${pagingTop} SELECT homepage_id, reader_idx, participation_field, participation_type, user_name, user_date, user_phone, protector_phone, user_email, postcode, address_base, address_detailed, approval_status, delete_yn, add_id, add_date FROM READER_CONTEST WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY reader_idx DESC ${pagingBottom}

mapper.update:
UPDATE
	READER_CONTEST
SET
	delete_yn = 'Y',
	delete_id = #{delete_id}
WHERE
	homepage_id = #{homepage_id}
AND reader_idx = #{reader_idx}

UPDATE
	READER_CONTEST
SET
	approval_status = #{approval_status}
WHERE
	homepage_id = #{homepage_id}
AND reader_idx = #{reader_idx}
